pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize bins with small post_residual to avoid creating unusable dead space
    if post_residual < 10 {
        score += (10 - post_residual) * 5.0; // Higher penalty for smaller gaps
    }

    // Favor bins with fewer open bins remaining
    score -= open_bins_count as f64 * 2.0;

    // Penalize if there are no fitting bins left
    if fitting_bins_count == 0 {
        score += bin_capacity as f64; // Large penalty if no space in any open bin
    }

    // Combine item size and residual to penalize large items in small spaces
    let item_residual = item_size - post_residual;
    if item_residual > 5 {
        score -= (item_residual - 5) * 3.0;
    }

    // Reward bins with high mean residual
    if mean_residual > 20.0 {
        score += (mean_residual - 20.0) * 1.0;
    }

    // Lookahead: Penalize bins where the next item would leave very little space
    let lookahead_penalty = if next_item_size > post_residual / 2 { 
        (next_item_size - post_residual / 2) as f64 * 5.0 
    } else { 0.0 };

    score -= lookahead_penalty;

    // Reward bins with higher bin capacity relative to item size
    let capacity_factor = bin_capacity as f64 / item_size as f64;
    if capacity_factor > 2.0 {
        score += (capacity_factor - 2.0) * 1.5;
    }

    score
}

